-- Private reference data, without executable HTML or authentication.
-- Chunk literals to keep each SQL statement below D1 limits.
CREATE TABLE IF NOT EXISTS _project_reference_seed (part INTEGER PRIMARY KEY, chunk TEXT NOT NULL);
DELETE FROM _project_reference_seed;
INSERT OR IGNORE INTO app_records(kind,id,value) SELECT 'project-report','farasan-reference',group_concat(chunk,'') FROM (SELECT chunk FROM _project_reference_seed ORDER BY part);
DROP TABLE _project_reference_seed;
